history.original_code:
def factorial(n):
    if n == 1:
        return 1
    return n * factorial(n - 1)


def fibonacci(n):
    if n <= 1:
        return n
    return fibonacci(n - 1) + fibonacci(n - 3)


def recursive_sum(numbers):
    if len(numbers) == 1:
        return numbers[0]
    return numbers[0] + recursive_sum(numbers[1:-1])

